import {applyGarmentSurface} from './garment-surface.js';
import * as T from './vendor/three.module.js';
import {releaseModel} from './studio-models.js';
export function createTailoring(body,legs,arms=[]){const extras=[];const root=new T.Group();root.name='tailored-body';root.userData.wardrobeSlot='garment';body.add(root);let key='',spec=null,mesh=null,rest=null,sleeping=false,rain=false;
 function set(v){const k=JSON.stringify(v);if(k===key)return;key=k;for(const c of [...root.children,...extras])releaseModel(c);extras.length=0;spec=v;mesh=null;if(!v)return;const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const c=canvas.getContext('2d');c.fillStyle=v.color;c.fillRect(0,0,256,256);c.fillStyle=v.accent;if(v.pattern==='check'){c.globalAlpha=.45;c.fillRect(0,0,128,256);c.fillRect(0,0,256,128)}if(v.pattern==='stripe'){c.fillRect(0,0,256,40);c.fillRect(0,128,256,40)}if(v.pattern==='dots')for(const [x,y]of [[64,64],[192,192]]){c.beginPath();c.arc(x,y,18,0,Math.PI*2);c.fill()}if(v.pattern==='flower')for(const [x,y]of [[64,64],[192,192]]){for(let i=0;i<5;i++){const a=i*Math.PI*2/5;c.beginPath();c.arc(x+Math.cos(a)*14,y+Math.sin(a)*14,10,0,Math.PI*2);c.fill()}}c.globalAlpha=1;const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;texture.wrapS=texture.wrapT=T.RepeatWrapping;texture.repeat.set(2*Math.PI*.35/(v.patternScale*2),.5/(v.patternScale*2));const material=new T.MeshPhysicalMaterial({map:texture,roughness:.95,sheen:.6,side:T.DoubleSide});
 applyGarmentSurface(material,v);
 if(v.kind==='top'||v.kind==='set')for(const arm of arms){const source=arm.getObjectByName('continuous-arm');if(!source)continue;const geo=source.geometry.clone(),pos=geo.attributes.position;for(let i=0;i<pos.count;i++){pos.setX(i,pos.getX(i)*1.08);pos.setZ(i,pos.getZ(i)*1.08)}geo.computeVertexNormals();const sleeveMaterial=v.artwork?.layout==='front'?applyGarmentSurface(new T.MeshPhysicalMaterial({color:v.color,side:T.DoubleSide}),{...v,artwork:null}):material.clone();const sleeve=new T.Mesh(geo,sleeveMaterial);sleeve.name='tailored-sleeve';arm.add(sleeve);extras.push(sleeve)}
 if(v.kind==='set'){const pants=applyGarmentSurface(new T.MeshPhysicalMaterial({color:v.pantsColor,roughness:.95,sheen:.6}),{...v,artwork:null});const hip=new T.Mesh(new T.LatheGeometry([new T.Vector2(.23,.17),new T.Vector2(.32,.255),new T.Vector2(.345,.34),new T.Vector2(.349,.40)],64),pants);hip.scale.z=.85;hip.name='tailored-trousers';root.add(hip);for(const leg of legs){const trouser=new T.Mesh(new T.LatheGeometry([new T.Vector2(.122,-.14),new T.Vector2(.142,-.08),new T.Vector2(.137,.03),new T.Vector2(.12,.08)],48),pants.clone());trouser.scale.z=1.13;trouser.position.z=.022;trouser.name='tailored-trouser-leg';leg.add(trouser);trouser.userData.wardrobeSlot="garment";extras.push(trouser)}}
 const rows=40,segments=96,positions=[],uv=[],indices=[],top=v.kind==='skirt'?.46:.715,bottom=['top','set'].includes(v.kind)?.46-v.length*.3:.46-v.length;
 for(let j=0;j<=rows;j++){const y=top+(bottom-top)*j/rows;const torso=.294+.058*Math.sin(Math.min(1,Math.max(0,(.715-y)/.33))*Math.PI/2);const t=Math.max(0,(.46-y)/v.length),r=y>=.46?torso:.348+v.flare*t;for(let i=0;i<=segments;i++){const a=i/segments*Math.PI*2,fold=v.pleats?Math.cos(a*v.pleats)*.01*t:0;positions.push(Math.sin(a)*(r+fold),y,Math.cos(a)*(r+fold)*.84);uv.push(i/segments,j/rows)}}for(let j=0;j<rows;j++)for(let i=0;i<segments;i++){const a=j*(segments+1)+i,b=a+segments+1;indices.push(a,b,a+1,b,b+1,a+1)}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(indices);g.computeVertexNormals();mesh=new T.Mesh(g,material);mesh.castShadow=mesh.receiveShadow=true;root.add(mesh);
 if(['top','set'].includes(v.kind)){
 const trim=new T.MeshStandardMaterial({color:v.accent,roughness:.85});
 const seam=new T.MeshStandardMaterial({color:new T.Color(v.color).multiplyScalar(.7),roughness:1});
 const ring=(radius,y,thickness,mat)=>{const m=new T.Mesh(new T.TorusGeometry(radius,thickness,8,80),mat);m.rotation.x=Math.PI/2;m.scale.y=.84;m.position.y=y;root.add(m);};
 ring(.296,.713,.009,trim);ring(.353,bottom+.008,.006,seam);
 if(v.kind==='set'){
 const rail=new T.Mesh(new T.BoxGeometry(.018,.29,.012),seam);rail.position.set(0,.55,.296);root.add(rail);
 const teeth=new T.MeshStandardMaterial({color:'#d5d8dc',roughness:.45,metalness:.35});
 for(let i=0;i<22;i++){const tooth=new T.Mesh(new T.BoxGeometry(.009,.004,.006),teeth);tooth.position.set(i%2?.004:-.004,.411+i*.012,.304);root.add(tooth);}
 const pull=new T.Mesh(new T.TorusGeometry(.008,.0025,6,12),teeth);pull.position.set(0,.685,.308);root.add(pull);
 for(const side of [-1,1]){const pocket=new T.Mesh(new T.BoxGeometry(.075,.047,.012),material.clone());pocket.position.set(side*.16,.51,.262);pocket.rotation.y=side*.38;root.add(pocket);const stitch=new T.Mesh(new T.BoxGeometry(.071,.003,.006),seam);stitch.position.set(side*.16,.53,.271);stitch.rotation.y=side*.38;root.add(stitch);}
 }
 }
 rest=Float32Array.from(positions);tick()}
 function tick(){root.visible=!!spec&&!sleeping&&!rain;for(const extra of extras)extra.visible=root.visible;if(!mesh||!root.visible)return;const sit=T.MathUtils.clamp(-Math.min(...legs.map(x=>x.rotation.x))/1.15,0,1),p=mesh.geometry.attributes.position;for(let i=0;i<p.count;i++){const x=rest[i*3],y=rest[i*3+1],z=rest[i*3+2],t=Math.max(0,(.46-y)/spec.length),front=T.MathUtils.smoothstep(z,-.03,.25);p.setXYZ(i,x,y+sit*t*front*.26,z+sit*t*front*.18)}p.needsUpdate=true;mesh.geometry.computeVertexNormals();mesh.geometry.computeBoundingSphere()}
 return {set,tick,sleep(v){sleeping=v;tick()},rain(v){rain=v;tick()}};
}
